import{_ as l,r as a,o,c as i,e as t,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Translatable - October CMS - 4.x","titleTemplate":false,"description":"Translate page properties for each site definition.","frontmatter":{"subtitle":"Translate page properties for each site definition."},"headers":[{"level":2,"title":"Available Properties","slug":"available-properties","link":"#available-properties","children":[]},{"level":2,"title":"Basic Usage","slug":"basic-usage","link":"#basic-usage","children":[]},{"level":2,"title":"Matching Sites to Locale Keys","slug":"matching-sites-to-locale-keys","link":"#matching-sites-to-locale-keys","children":[]},{"level":2,"title":"Locale Fallback Logic","slug":"locale-fallback-logic","link":"#locale-fallback-logic","children":[]},{"level":2,"title":"URL Routing","slug":"url-routing","link":"#url-routing","children":[]},{"level":2,"title":"Translated Properties","slug":"translated-properties","link":"#translated-properties","children":[]},{"level":2,"title":"Accessing Values in Twig","slug":"accessing-values-in-twig","link":"#accessing-values-in-twig","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/cms/components/translatable.md","filePath":"4.x/cms/components/translatable.md"}'),p={name:"4.x/cms/components/translatable.md"};function d(u,e,h,g,k,m){const s=a("pre-heading"),n=a("post-heading");return o(),i("div",null,[t(s),e[0]||(e[0]=c("h1",null,"Translatable",-1)),t(n),e[1]||(e[1]=r(`<p>The <code>translatable</code> component stores translated page properties for each <a href="./../multisite/multisite.html">site definition</a>, including the page URL, title, description and meta fields. Adding the component to a page is how the page opts in to per-site translations.</p><h2 id="available-properties"><a href="#available-properties" class="header-anchor">#</a> Available Properties</h2><p>The following properties are supported by the component.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>locales</strong></td><td>A collection of translated values, keyed by locale.</td></tr></tbody></table></div><p>Each entry in the <code>locales</code> collection supports the following fields. Any field left out falls back to the value defined by the page itself.</p><div class="table"><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>url</strong></td><td>The page URL used when the matching site is active.</td></tr><tr><td><strong>title</strong></td><td>The translated page title.</td></tr><tr><td><strong>description</strong></td><td>The translated page description.</td></tr><tr><td><strong>meta_title</strong></td><td>The translated meta title.</td></tr><tr><td><strong>meta_description</strong></td><td>The translated meta description.</td></tr></tbody></table></div><h2 id="basic-usage"><a href="#basic-usage" class="header-anchor">#</a> Basic Usage</h2><p>The following example defines a contact page with French and Russian translations. The entries are keyed by the locale of the matching site definition.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/contact</span>&quot;</span>
<span class="token key attr-name">title</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Contact</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">translatable</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">locales[fr][url]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/contactez</span>&quot;</span>
<span class="token key attr-name">locales[fr][title]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Contactez</span>&quot;</span>
<span class="token key attr-name">locales[ru][url]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/контакт</span>&quot;</span>
<span class="token key attr-name">locales[ru][title]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Контакт</span>&quot;</span>
</code></pre></div><p>When editing the page in the backend, the component displays a managed list where each entry contains the translated fields for a single locale. Entries only need to be added for the sites that require translation.</p><h2 id="matching-sites-to-locale-keys"><a href="#matching-sites-to-locale-keys" class="header-anchor">#</a> Matching Sites to Locale Keys</h2><p>When values are resolved for the active site, the keys in the <code>locales</code> collection are checked against the site&#39;s locale in the following order, where the first match wins.</p><ol><li>The exact site locale, for example <code>en-AU</code>.</li><li>The base language of the locale, for example <code>en</code>.</li></ol><p>This means a regional locale automatically falls back to its base language when no exact entry exists.</p><h2 id="locale-fallback-logic"><a href="#locale-fallback-logic" class="header-anchor">#</a> Locale Fallback Logic</h2><p>Values are resolved for each field independently, so a regional locale can override a single field and inherit the rest from the base language entry. In the following example, two site definitions use the <code>en-AU</code> and <code>en-GB</code> locales. Both sites use the shared English title, and the Australian site only overrides the URL.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/contact</span>&quot;</span>
<span class="token key attr-name">title</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Contact</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">translatable</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">locales[en][title]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Contact Us</span>&quot;</span>
<span class="token key attr-name">locales[en-AU][url]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/contact-au</span>&quot;</span>
</code></pre></div><h2 id="url-routing"><a href="#url-routing" class="header-anchor">#</a> URL Routing</h2><p>When a site with a matching locale is active, the translated URL replaces the page URL in the routing table, including any route parameters defined in the pattern.</p><ul><li><code>/contactez</code> displays the page on the French site and <code>/contact</code> responds with a redirect to <code>/contactez</code>.</li><li><code>/contact</code> displays the page on every other site and <code>/contactez</code> is not found.</li></ul><p>The default URL redirects to its translated URL with a <code>301</code> permanent redirect status code.</p><p>Links generated for the page follow the same rules, so the <code>|page</code> filter, menus and sitemaps produce the translated URL automatically. The <a href="./sitepicker.html">Site Picker component</a> and <code>hreflang</code> links resolve the translated URL for each alternative site.</p><div class="custom-block tip"><p>When using the route cache created by the <code>theme:cache</code> command, run the command again after adding site definitions or changing translated URLs so the cached route maps are rebuilt.</p></div><h2 id="translated-properties"><a href="#translated-properties" class="header-anchor">#</a> Translated Properties</h2><p>The remaining fields are applied to the page automatically when it renders, so <code>{{ this.page.title }}</code> returns the translated title when the French site is active, along with any other translated value found in the matching locale entry. The backend always displays the original values for editing.</p><h2 id="accessing-values-in-twig"><a href="#accessing-values-in-twig" class="header-anchor">#</a> Accessing Values in Twig</h2><p>Any custom field can be included in a locale entry and resolved manually with the <code>siteProperty</code> method, which matches the active site using the same locale key order.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">translatable</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">locales[fr][banner]</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Bienvenue</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> translatable<span class="token punctuation">.</span>siteProperty<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>banner<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token operator">|</span>default<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>Welcome<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>The <code>siteProperties</code> method returns every translated value for the active site as an array, merged across the matching locale keys.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> translated <span class="token operator">=</span> translatable<span class="token punctuation">.</span>siteProperties <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../multisite/multisite.html">Multisite</a></li><li><a href="./sitepicker.html">Site Picker</a></li></ul></div>`,32))])}const b=l(p,[["render",d]]);export{f as __pageData,b as default};
